package cn.jingyu.deepseek.test;
import cn.jingyu.deepseek.NativeActivity;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import cn.jingyu.deepseek.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.atomic.AtomicReference;

public final class NativeSmokeTest extends Instrumentation{
 private NativeActivity activity;private String key;private final StringBuilder report=new StringBuilder();
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 private Object field(String name)throws Exception{Field f=NativeActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private String texts(View view){String value=view instanceof TextView?((TextView)view).getText().toString()+"\n":"";if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)value+=texts(((ViewGroup)view).getChildAt(i));return value;}
 private void check(boolean value,String message){if(!value)throw new AssertionError(message);report.append("PASS ").append(message).append('\n');}
 private void main(Runnable action){runOnMainSync(action);waitForIdleSync();}
 private void send(String value)throws Exception{main(()->{try{((EditText)field("input")).setText(value);((Button)field("send")).performClick();}catch(Exception e){throw new RuntimeException(e);}});check(texts(activity.getWindow().getDecorView()).contains(value),"own message visible immediately");long due=System.currentTimeMillis()+65000;while(System.currentTimeMillis()<due){AtomicReference<Boolean> busy=new AtomicReference<>(true);main(()->{try{busy.set((Boolean)field("busy"));}catch(Exception e){throw new RuntimeException(e);}});if(!busy.get())return;SystemClock.sleep(250);}throw new AssertionError("UI request did not complete");}
 @Override public void onStart(){Bundle result=new Bundle();try{
  File secret=new File(getTargetContext().getFilesDir(),"test-key");try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(secret),"UTF-8"))){key=r.readLine();}secret.delete();
  LocalStore store=new LocalStore(getTargetContext());store.key(key);
  for(String fileName:new String[]{"control.txt","notes.docx","grades.xlsx","feedback.pdf"}){android.net.Uri uri=android.net.Uri.fromFile(new File(getTargetContext().getFilesDir(),fileName));java.util.List<JSONObject> files;try{files=DocumentReader.parse(getTargetContext(),uri);}catch(Exception failure){report.append("FILE ").append(fileName).append(" detected=").append(DocumentReader.name(getTargetContext(),uri)).append(" bytes=").append(DocumentReader.bytes(getTargetContext(),uri,10000000).length).append('\n');throw failure;}check(!files.isEmpty(),"native file parsed: "+fileName);if(fileName.endsWith(".pdf"))check(files.get(0).optString("data").startsWith("data:image/jpeg;base64,"),"PDF rendered for Flash vision");else check(!files.get(0).optString("text").isEmpty(),"document text extracted: "+fileName);}
  JSONObject old=new JSONObject().put("chats",new JSONArray().put(new JSONObject().put("id","legacy").put("title","旧版历史测试").put("updated",1).put("messages",new JSONArray().put(new JSONObject().put("id","legacy-u").put("role","user").put("text","旧版保留的消息").put("files",new JSONArray()).put("status","complete"))))).put("current","legacy").put("effort","off").put("maxTokens",2048);
  store.save(old.toString());activity=(NativeActivity)startActivitySync(new Intent(getTargetContext(),NativeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
  check(texts(activity.getWindow().getDecorView()).contains("旧版保留的消息"),"legacy history visible on launch");
  main(()->{try{java.util.List<JSONObject> pending=(java.util.List<JSONObject>)field("pending");pending.addAll(DocumentReader.parse(getTargetContext(),android.net.Uri.fromFile(new File(getTargetContext().getFilesDir(),"control.txt"))));Method render=NativeActivity.class.getDeclaredMethod("renderAttachments");render.setAccessible(true);render.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});
  send("只回复：原生测试成功");String first=texts(activity.getWindow().getDecorView());check(first.contains("原生测试成功"),"native compatible response visible");JSONObject state=(JSONObject)field("state");JSONArray messages=state.getJSONArray("chats").getJSONObject(0).getJSONArray("messages");JSONObject last=messages.getJSONObject(messages.length()-1);check(last.optString("status").equals("complete")&&last.optString("text").contains("原生测试成功"),"compatible request completed with answer");check(messages.getJSONObject(messages.length()-2).getJSONArray("files").length()==1,"text attachment sent with actual API question");
  main(()->{try{((JSONObject)field("state")).put("streaming",true);((Spinner)field("effort")).setSelection(1);}catch(Exception e){throw new RuntimeException(e);}});send("只回复：流式测试成功");check(texts(activity.getWindow().getDecorView()).contains("流式测试成功"),"streaming response visible");
  main(()->{try{JSONObject current=(JSONObject)field("state");current.put("streaming",false);((Spinner)field("effort")).setSelection(0);java.util.List<JSONObject> pending=(java.util.List<JSONObject>)field("pending");pending.addAll(DocumentReader.parse(getTargetContext(),android.net.Uri.fromFile(new File(getTargetContext().getFilesDir(),"feedback.pdf"))));Method render=NativeActivity.class.getDeclaredMethod("renderAttachments");render.setAccessible(true);render.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});send("请读取附件中的英文，用英文原样写出这一句，不要其他内容。");JSONObject visionState=(JSONObject)field("state");JSONArray visionMessages=visionState.getJSONArray("chats").getJSONObject(0).getJSONArray("messages");JSONObject vision=visionMessages.getJSONObject(visionMessages.length()-1);String visionText=vision.optString("text").toLowerCase(java.util.Locale.ROOT);check(vision.optString("status").equals("complete"),"actual Flash API accepts PDF page image attachment");check(visionText.contains("feedback")&&visionText.contains("control error"),"actual Flash reply reads text from rendered PDF page");
  Bitmap screenshot=getUiAutomation().takeScreenshot();ByteArrayOutputStream image=new ByteArrayOutputStream();screenshot.compress(Bitmap.CompressFormat.PNG,100,image);result.putString("screenshot64",android.util.Base64.encodeToString(image.toByteArray(),android.util.Base64.NO_WRAP));screenshot.recycle();
  main(()->activity.finish());SystemClock.sleep(700);activity=(NativeActivity)startActivitySync(new Intent(getTargetContext(),NativeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(((JSONObject)field("state")).toString().contains("原生测试成功"),"history survives activity restart");
  store.key("sk-invalid-test");send("错误处理测试");check(texts(activity.getWindow().getDecorView()).contains("API Key 无效"),"invalid key error visible without blank screen");store.key("");key=null;result.putString("report",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("report",report+"FAIL "+error.getClass().getSimpleName()+": "+error.getMessage());try{new LocalStore(getTargetContext()).key("");}catch(Exception ignored){}finish(Activity.RESULT_CANCELED,result);}}
}
